def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    bottom = max(r for r,c in cells)
    out = [[0]*w for _ in range(h)]
    for r,c in cells:
        nc = c - (bottom-r)
        if 0 <= nc < w:
            out[r][nc] = grid[r][c]
    return out
